contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // params: depositAmt to fund a prior deposit, collectAmt to attempt collecting, minSum to set MinSum
    function run(uint depositAmt, uint collectAmt, uint minSum) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmt)); require(depositAmt <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmt);

        // initialize C so state is consistent
        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.SetLogFile(address(0)); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        // make a deposit so this contract has a recorded balance to attempt Collect
        c.Deposit{value: depositAmt}(); if (__ESBMC_reverted()) return;

        // observe before-values
        uint bal_before = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint contract_bal_before = address(c).balance;

        bool reverted;
        c.Collect(collectAmt); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint bal_after = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint contract_bal_after = address(c).balance;

        // General rule: If Collect succeeded then both the recorded balance and contract balance do not increase; if it reverted, both are unchanged.
        assert(
            (!reverted && bal_after <= bal_before && contract_bal_after <= contract_bal_before)
            || (reverted && bal_after == bal_before && contract_bal_after == contract_bal_before)
        );
    }

    receive() external payable { }
}

