// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 depositAmt, uint256 collectAmt, uint256 minSum) internal {
        depositAmt = bound(depositAmt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmt);
        try c.SetMinSum(minSum) {} catch { return; }
        try c.SetLogFile(address(0)) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.Deposit{value: depositAmt}() {} catch { return; }
        uint256 bal_before;
        try c.balances(address(this)) returns (uint256 __r) { bal_before = __r; } catch { return; }
        uint contract_bal_before = address(c).balance;
        bool reverted;
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 bal_after;
        try c.balances(address(this)) returns (uint256 __r) { bal_after = __r; } catch { return; }
        uint contract_bal_after = address(c).balance;
        assertTrue((!reverted && bal_after <= bal_before && contract_bal_after <= contract_bal_before)
            || (reverted && bal_after == bal_before && contract_bal_after == contract_bal_before));
    }

    function testFuzz_run(uint256 depositAmt, uint256 collectAmt, uint256 minSum) public {
        _run(depositAmt, collectAmt, minSum);
    }

    receive() external payable { }
}
